def solve3(g):
    a=np.array(g); H,W=a.shape
    occ=set(map(tuple,np.argwhere(a!=0)))
    cells_all=[(y,x) for y,x in zip(*np.where(a!=0))]
    seen=set(); objs=[]
    for c in cells_all:
        if c in seen: continue
        col=a[c]; stack=[c]; comp=[]
        while stack:
            p=stack.pop()
            if p in seen: continue
            seen.add(p); comp.append(p)
            y,x=p
            for q in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
                if 0<=q[0]<H and 0<=q[1]<W and q not in seen and a[q]==col: stack.append(q)
        objs.append(comp)
    objs.sort(key=lambda c: -max(x for y,x in c))
    for cells in objs:
        for p in cells: occ.discard(p)
        best=0
        for d in range(1,W):
            new=[(y,x+d) for y,x in cells]
            if any(x+d>=W for y,x in cells) or any(p in occ for p in new): break
            best=d
        for y,x in cells:
            occ.add((y,x+best)); a[y,x+best]=a[y,x]
            if best: a[y,x]=0
    return a.tolist()
